// Exercise Util::addressOf with several object types. Ensure TYPE is an object type
// and the argument is a valid lvalue. Validate that the returned pointer equals the
// built-in address for non-overloaded types.
{
    // 1) Built-in scalar type
    int ai = *FUZZ_PARAM(int);            // generate stable value
    int *pi = BloombergLP::bsls::Util::addressOf(ai);
    // For object types without overloaded operator&, addressOf must equal &obj
    FUZZ_ASSERT(pi == &ai, "addressOf(int) must return the true address");
}
{
    // 2) Another scalar type to cover a different instantiation
    double ad = *FUZZ_PARAM(double);
    double *pd = BloombergLP::bsls::Util::addressOf(ad);
    FUZZ_ASSERT(pd == &ad, "addressOf(double) must return the true address");
}
{
    // 3) POD aggregate type (no overloaded operator&)
    struct Pod { int x; long y; };
    Pod ap{ *FUZZ_PARAM(int), (long)(*FUZZ_PARAM(int)) };
    Pod *pp = BloombergLP::bsls::Util::addressOf(ap);
    FUZZ_ASSERT(pp == &ap, "addressOf(Pod) must return the true address");
}
